/* ===== تتبع الزوار ===== */
function client_ip(){foreach(['HTTP_CF_CONNECTING_IP','HTTP_X_REAL_IP','HTTP_X_FORWARDED_FOR'] as $h)if(!empty($_SERVER[$h])){$i=trim(explode(',',$_SERVER[$h])[0]);if(filter_var($i,FILTER_VALIDATE_IP))return $i;}return $_SERVER['REMOTE_ADDR']??'';}
function ua_info($u){$bot=(!$u||preg_match('/bot|crawl|spider|slurp|facebookexternalhit|preview|monitor|curl|wget|python|httpclient|headless|lighthouse|pingdom|uptime|scan/i',$u))?1:0;
$dev=preg_match('/iPad|Tablet|Android(?!.*Mobile)/i',$u)?'تابلت':(preg_match('/Mobi|iPhone|iPod|Android/i',$u)?'جوال':'حاسوب');
$br=match(true){(bool)preg_match('/Snapchat/i',$u)=>'Snapchat',(bool)preg_match('/Instagram/i',$u)=>'Instagram',(bool)preg_match('/FBAN|FBAV/i',$u)=>'Facebook',(bool)preg_match('/TikTok|musical_ly/i',$u)=>'TikTok',(bool)preg_match('/Edg/i',$u)=>'Edge',(bool)preg_match('/OPR|Opera/i',$u)=>'Opera',(bool)preg_match('/SamsungBrowser/i',$u)=>'Samsung',(bool)preg_match('/Firefox/i',$u)=>'Firefox',(bool)preg_match('/Chrome|CriOS/i',$u)=>'Chrome',(bool)preg_match('/Safari/i',$u)=>'Safari',default=>'أخرى'};
$os=match(true){(bool)preg_match('/Windows/i',$u)=>'Windows',(bool)preg_match('/Android/i',$u)=>'Android',(bool)preg_match('/iPhone|iPad|iPod/i',$u)=>'iOS',(bool)preg_match('/Mac OS X/i',$u)=>'macOS',(bool)preg_match('/Linux/i',$u)=>'Linux',default=>'أخرى'};
return [$dev,$br,$os,$bot];}
function flag($cc){return preg_match('/^[A-Za-z]{2}$/',(string)$cc)?mb_chr(0x1F1E6+ord(strtoupper($cc[0]))-65).mb_chr(0x1F1E6+ord(strtoupper($cc[1]))-65):'🌐';}
function ck($n,$v,$ex){setcookie($n,$v,['expires'=>$ex,'path'=>'/','samesite'=>'Lax','httponly'=>true,'secure'=>!empty($_SERVER['HTTPS'])]);$_COOKIE[$n]=$v;}
function track($path){global $db;if(!cfg('track_visits',true)||isset($_COOKIE['adm'])||headers_sent())return;[$dev,$br,$os,$bot]=ua_info($_SERVER['HTTP_USER_AGENT']??'');
$vid=$_COOKIE['vid']??'';$sid=$_COOKIE['sid']??'';
if(!$bot){if(!preg_match('/^[a-f0-9]{16}$/',$vid))$vid=bin2hex(random_bytes(8));ck('vid',$vid,time()+63072000);if(!preg_match('/^[a-f0-9]{16}$/',$sid))$sid=bin2hex(random_bytes(8));ck('sid',$sid,time()+1800);}
$ip=client_ip();$ref=(string)($_SERVER['HTTP_REFERER']??'');$rh=parse_url($ref,PHP_URL_HOST);if($rh&&$rh==($_SERVER['HTTP_HOST']??''))$ref='';
$cc=strtoupper(substr((string)($_SERVER['HTTP_CF_IPCOUNTRY']??''),0,2));if($cc=='XX')$cc='';
$db->prepare('INSERT INTO visits(t,vid,sid,ip,path,ref,ua,dev,br,os,cc,bot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([time(),$vid,$sid,$ip,'/'.$path,mb_substr($ref,0,300),mb_substr($_SERVER['HTTP_USER_AGENT']??'',0,300),$dev,$br,$os,$cc,$bot]);}
function geo_resolve($limit=60){global $db;if(!cfg('geo_lookup',true))return;$ips=$db->query("SELECT DISTINCT ip FROM (SELECT ip FROM visits UNION SELECT ip FROM logins) WHERE ip NOT IN (SELECT ip FROM geo) AND ip!='' LIMIT $limit")->fetchAll(PDO::FETCH_COLUMN);
$q=[];foreach($ips as $ip){if(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE))$q[]=['query'=>$ip,'fields'=>'status,country,countryCode,city,query','lang'=>'ar'];else $db->prepare('INSERT OR REPLACE INTO geo VALUES(?,?,?,?,?)')->execute([$ip,'','محلي','',time()]);}
if(!$q||!function_exists('curl_init'))return;$c=curl_init('http://ip-api.com/batch');curl_setopt_array($c,[CURLOPT_POST=>1,CURLOPT_POSTFIELDS=>json_encode($q),CURLOPT_RETURNTRANSFER=>1,CURLOPT_TIMEOUT=>4,CURLOPT_CONNECTTIMEOUT=>2]);$r=json_decode((string)curl_exec($c),true);curl_close($c);
if(!is_array($r))return;$st=$db->prepare('INSERT OR REPLACE INTO geo VALUES(?,?,?,?,?)');foreach($r as $x)if(($x['status']??'')=='success')$st->execute([$x['query'],$x['countryCode']??'',$x['country']??'',$x['city']??'',time()]);}
